  const sub = (state.subtitle || '').trim();
  let subY = y + h * 0.72;
  if (sub) {
    const subSize = Math.round(h * 0.17);
    ctx.font = `${subSize}px Pacifico, cursive`;
    ctx.shadowColor = grade.overlay[1];
    ctx.shadowBlur = subSize * 0.9;
