    const crop = state.panels[i] || { photoId: null, zoom: 1, ox: 0.5, oy: 0.65 };
    const photo = (crop.photoId && byId.get(crop.photoId)) || fallback;
    if (photo) drawGradedPhoto(ctx, photo, rect, grade, crop);
